        fMaxLimit       := 100.0,
        fMinLimit       := 0.0,
        fOut            => rUnwindBrakeTorque
    );

    // If the unwind spool is getting critically small, warn or soft-stop
    IF rUnwindDiameterSensor < 150.0 THEN // mm
