    END_IF;

    // =========================================================================
    // 3. MAIN MACHINE STATE MACHINE & SEAL SYNCHRONIZATION
    // =========================================================================
    CASE eState OF
        0: // INIT
            xMachineFault := FALSE;
            IF xEnableRun AND NOT xSterilityFault THEN
                eState := 1; // HOMING
            END_IF;

        1: // HOMING
            // Wait for servo systems (Seal Jaws) to home
