FUNCTION_BLOCK FB_LHe_PhaseTracker
VAR_INPUT
    Pressure : REAL; (* bar *)
    Temperature : REAL; (* K *)
END_VAR
VAR_OUTPUT
    IsSuperfluid : BOOL;
    IsSupercritical : BOOL;
    SubcoolingMargin : REAL; (* K *)
END_VAR
VAR
    LambdaPoint_T : REAL := 2.1768; (* K at lambda point *)
    Critical_T : REAL := 5.1953; (* K *)
    Critical_P : REAL := 2.275; (* bar *)
END_VAR
    (* Phase determination logic based on He thermodynamic properties *)
    IsSuperfluid := (Temperature < LambdaPoint_T) AND (Pressure < Critical_P);
    IsSupercritical := (Temperature > Critical_T) AND (Pressure > Critical_P);

    IF IsSuperfluid THEN
        SubcoolingMargin := LambdaPoint_T - Temperature;
    ELSE
        SubcoolingMargin := 0.0;
    END_IF;
END_FUNCTION_BLOCK


FUNCTION_BLOCK FB_QuenchDetector
VAR_INPUT
    Sensors : S_MagnetSensors;
    Threshold_dT_dt : REAL := 0.05; (* K/ms *)
    Threshold_dV_dt : REAL := 0.10; (* V/s - Inductive compensated *)
END_VAR
VAR_OUTPUT
    QuenchDetected : BOOL;
END_VAR
VAR
    PrevTemp1, PrevTemp2, PrevTemp3 : REAL;
    PrevVoltA, PrevVoltB : REAL;
    FilterCount : INT;
END_VAR
    (* Calculate rate of change for temperatures *)
    IF (Sensors.Temp_Local_1 - PrevTemp1) > Threshold_dT_dt OR 
       (Sensors.Temp_Local_2 - PrevTemp2) > Threshold_dT_dt OR
       (Sensors.Temp_Local_3 - PrevTemp3) > Threshold_dT_dt THEN
        FilterCount := FilterCount + 1;
    ELSE
        FilterCount := 0;
    END_IF;

    (* Resistive voltage growth check *)
    IF ABS(Sensors.Voltage_Tap_A - Sensors.Voltage_Tap_B) > Threshold_dV_dt THEN
        FilterCount := FilterCount + 2;
    END_IF;

    IF FilterCount >= 3 THEN
        QuenchDetected := TRUE;
    ELSE
        QuenchDetected := FALSE;
    END_IF;

    (* Store previous values for next scan *)
    PrevTemp1 := Sensors.Temp_Local_1;
    PrevTemp2 := Sensors.Temp_Local_2;
    PrevTemp3 := Sensors.Temp_Local_3;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_SuperconductingMagnetRingCtrl
VAR_INPUT
    Enable              : BOOL;
    Reset               : BOOL;
    MagnetData          : S_MagnetSensors;
    CompressorFbk       : S_CompressorVFD;
END_VAR
VAR_OUTPUT
    State               : E_CryoState;
    QuenchHeatersTrig   : BOOL;
    EnergyExtraction    : BOOL;
    CompressorCmd       : S_CompressorVFD;
    ControlValveLHe     : REAL; (* 0-100% *)
    DumpValve           : BOOL;
END_VAR
VAR
    PhaseTracker        : FB_LHe_PhaseTracker;
    QuenchDet           : FB_QuenchDetector;
    TargetTemp          : REAL := 1.9; (* K *)
    PID_Error           : REAL;
    PID_Integral        : REAL;
    VFD_RampRate        : REAL := 2.0; (* Hz/s *)
END_VAR

    (* Instantiations *)
    PhaseTracker(Pressure := MagnetData.LHe_Pressure, Temperature := MagnetData.Temp_Local_1);
    QuenchDet(Sensors := MagnetData);

    (* Global Safety Interlock: Quench Protection overrides everything *)
    IF QuenchDet.QuenchDetected THEN
        State := CRYO_QUENCH_DETECTED;
    END_IF;

    CASE State OF
        CRYO_IDLE:
            QuenchHeatersTrig := FALSE;
            EnergyExtraction := FALSE;
            DumpValve := FALSE;
            ControlValveLHe := 0.0;
            CompressorCmd.RunCmd := FALSE;
            CompressorCmd.SpeedRef := 0.0;

            IF Enable AND Reset THEN
                State := CRYO_COOLDOWN;
            END_IF;

        CRYO_COOLDOWN:
            (* Sequence Magnetic Bearings for Cold Compressor first *)
            IF NOT CompressorFbk.BearingActive THEN
                CompressorCmd.BearingActive := TRUE;
            ELSIF CompressorFbk.MagneticBearingX < 50.0 AND CompressorFbk.MagneticBearingY < 50.0 THEN
                (* Bearings levitated and stable, clear to run VFD *)
                CompressorCmd.RunCmd := TRUE;
                CompressorCmd.SpeedRef := MIN(CompressorCmd.SpeedRef + VFD_RampRate, 30.0);
            END_IF;

            IF MagnetData.Temp_Local_1 < 4.5 THEN
                State := CRYO_PUMP_DOWN;
            END_IF;

        CRYO_PUMP_DOWN:
            (* Drop pressure to achieve 1.9K superfluid helium *)
            CompressorCmd.SpeedRef := MIN(CompressorCmd.SpeedRef + VFD_RampRate, 90.0);
            ControlValveLHe := 60.0;

            IF PhaseTracker.IsSuperfluid AND MagnetData.Temp_Local_1 <= TargetTemp THEN
                State := CRYO_SUPERFLUID_NOMINAL;
            END_IF;

        CRYO_SUPERFLUID_NOMINAL:
            (* Maintain exactly 1.9K via PI Control on Cold Compressor VFD *)
            PID_Error := TargetTemp - MagnetData.Temp_Local_1;
            PID_Integral := PID_Integral + (PID_Error * 0.01);
            CompressorCmd.SpeedRef := 90.0 + (PID_Error * 50.0) + PID_Integral;

            (* Bound VFD Speed *)
            IF CompressorCmd.SpeedRef > 120.0 THEN CompressorCmd.SpeedRef := 120.0; END_IF;
            IF CompressorCmd.SpeedRef < 60.0 THEN CompressorCmd.SpeedRef := 60.0; END_IF;

            (* Magnetic Bearing fault triggers abort *)
            IF CompressorFbk.Fault OR NOT CompressorFbk.BearingActive THEN
                State := CRYO_FAST_ABORT;
            END_IF;

        CRYO_QUENCH_DETECTED:
            (* INSTANT ACTION: Dissipate stored magnetic energy *)
            QuenchHeatersTrig := TRUE; (* Fire heaters across entire volume *)
            EnergyExtraction := TRUE;  (* Switch resistors into circuit *)
            DumpValve := TRUE;         (* Vent boiled-off gas *)
            ControlValveLHe := 0.0;    (* Isolate supply *)

            (* Safely spin down compressor *)
            CompressorCmd.SpeedRef := 0.0;
            CompressorCmd.RunCmd := FALSE;

            IF Reset AND MagnetData.Temp_Local_1 < 80.0 THEN
                State := CRYO_IDLE;
            END_IF;

        CRYO_FAST_ABORT:
            ControlValveLHe := 0.0;
            DumpValve := TRUE;
            CompressorCmd.SpeedRef := 0.0;
            CompressorCmd.RunCmd := FALSE;

            IF Reset THEN
                State := CRYO_IDLE;
            END_IF;

    END_CASE;
END_FUNCTION_BLOCK
